"""Visible scored-process profile: Java threads are allowed, child processes are not."""
import ctypes,errno,os,platform,resource,signal,sys

def restrict(cpu=60):
    if os.geteuid()==0 or platform.machine()!='x86_64':raise RuntimeError('nonroot Linux x86_64 required')
