    class Program(ctypes.Structure):_fields_=[('len',ctypes.c_ushort),('filter',ctypes.POINTER(Filter))]
    rows=[(0x20,0,0,4),(0x15,1,0,0xc000003e),(0x06,0,0,0x80000000),(0x20,0,0,0),(0x35,0,1,0x40000000),(0x06,0,0,0x80000000)]
    denied=[41,42,29,30,31,64,65,66,220,68,69,70,71,62,200,234,101,310,311,272,308,165,166,155,161,112,109,105,106,113,114,117,119,116,304,303,321,250,248,249,298,323,425,426,427,438,57,58]
    for n in denied:rows.extend([(0x15,0,1,n),(0x06,0,0,0x50000|errno.EPERM)])
    # JDK NIO uses a local AF_UNIX pair for its pre-close descriptor.
    rows.extend([(0x15,0,4,53),(0x20,0,0,16),(0x15,1,0,1),
                 (0x06,0,0,0x50000|errno.EPERM),(0x20,0,0,0)])
    # clone3 returns ENOSYS; clone is limited to threads, without namespaces.
    rows.extend([(0x15,0,1,435),(0x06,0,0,0x50000|errno.ENOSYS),
                 (0x15,0,6,56),(0x20,0,0,16),(0x45,1,0,0x10000),(0x06,0,0,0x50000|errno.EPERM),
                 (0x45,0,1,0x7e820000),(0x06,0,0,0x50000|errno.EPERM),(0x20,0,0,0),
                 (0x06,0,0,0x7fff0000)])
    array=(Filter*len(rows))(*(Filter(*r) for r in rows));prog=Program(len(rows),array)
    libc=ctypes.CDLL(None,use_errno=True)
    for option,value in [(4,0),(38,1)]:
        if libc.prctl(option,value,0,0,0):raise OSError(ctypes.get_errno(),'prctl')
    if libc.prctl(22,2,ctypes.byref(prog),0,0):raise OSError(ctypes.get_errno(),'seccomp')
    signal.pthread_sigmask(signal.SIG_UNBLOCK,{signal.SIGINT,signal.SIGTERM})

if __name__=='__main__':
    restrict()
